+static int omci_get_sw_version(char *sw_version, size_t size)
+{
+	FILE *fp = NULL;
+	char buffer[16] = {0};
+
+	if (sw_version == NULL || size == 0) {
+		return -1;
+	}
+
+	fp = fopen("/etc/fw_info/version", "r");
+	if (fp == NULL) {
+		return -1;
+	}
+
+	if (fgets(buffer, sizeof(buffer), fp) == NULL) {
+		fclose(fp);
+		return -1;
+	}
+
+	fclose(fp);
+
+	buffer[strcspn(buffer, "\r\n")] = '\0';
+
+	if (buffer[0] != '\0') {
+		snprintf(sw_version, size, "HNI-%s", buffer);
+	} else {
+		snprintf(sw_version, size, "HNI-SW-V1.0");
+	}
+
+	return 0;
